#!/usr/bin/env python3
"""cargo-about の JSON 出力から THIRDPARTYNOTICES.md を生成する。

使い方（make thirdparty から呼ばれる）:
    cargo about generate --format json | python3 thirdparty/build_notices.py thirdparty/native-libs.md > THIRDPARTYNOTICES.md

cargo-about は本文が完全一致するものだけをまとめるため、著作権表記が違うだけの同一ライセンス文が
大量に重複する。ここでは著作権表記の行を除いた本文が同じものを1つにまとめ、本文は1回だけ載せる。
著作権表記はクレートごとに残す（MIT/BSD/ISC は表記の保持が必須のため）。
"""
import collections
import json
import re
import sys

SELF_CRATE = "nekoviewer"
# 「Copyright (c) ...」「Copyright 2019 ...」「Copyright © ...」で始まる行を著作権表記とみなす。
# Apache-2.0 本文の "Copyright [yyyy] [name of copyright owner]" は該当しない。
NOTICE_RE = re.compile(r"^[ \t]*copyright[ \t]*(\(c\)|©|[0-9])", re.IGNORECASE)


def split_notices(text):
    """本文から著作権表記の行を取り出し、(表記の一覧, 表記を除いた本文) を返す。"""
    notices, body = [], []
    for line in text.splitlines():
        if NOTICE_RE.match(line):
            notices.append(line.strip())
        else:
            body.append(line)
    return notices, "\n".join(body)


def normalize(body):
    return re.sub(r"\s+", " ", body).strip()


def tidy(body):
    """表記を除いた後に残る連続空行を詰める。"""
    return re.sub(r"\n{3,}", "\n\n", body).strip("\n")


def crate_label(crate):
    url = crate.get("repository") or "https://crates.io/crates/" + crate["name"]
    return "[%s %s](%s)" % (crate["name"], crate["version"], url)


def main():
    native_path = sys.argv[1] if len(sys.argv) > 1 else None
    data = json.load(sys.stdin)

    # ライセンス名 -> 正規化本文 -> {body, entries[(notices, crates)]}
    licenses = collections.OrderedDict()
    for lic in data["licenses"]:
        crates = [u["crate"] for u in lic["used_by"] if u["crate"]["name"] != SELF_CRATE]
        if not crates:
            continue
        notices, body = split_notices(lic["text"])
        variants = licenses.setdefault(lic["name"], collections.OrderedDict())
        v = variants.setdefault(normalize(body), {"body": tidy(body), "entries": []})
        v["entries"].append((notices, crates))

    out = []
    out.append("# Third-Party Notices\n")
    out.append("Nekoviewer uses the following third-party software.")
    out.append("Nekoviewer が利用しているサードパーティ製ソフトウェアのライセンス表記です。\n")
    out.append("This file is generated by `make thirdparty` (cargo-about + `thirdparty/build_notices.py`) "
               "and `thirdparty/native-libs.md`. Do not edit it by hand.\n")
    out.append("## Rust crates / Rust クレート\n")

    for name, variants in licenses.items():
        count = sum(len(c) for v in variants.values() for _, c in v["entries"])
        out.append("- %s (%d)" % (name, count))
    out.append("")

    for name, variants in licenses.items():
        for i, v in enumerate(variants.values(), 1):
            suffix = "" if len(variants) == 1 else " (%d/%d)" % (i, len(variants))
            out.append("### %s%s\n" % (name, suffix))
            out.append("Crates and copyright notices:\n")
            for notices, crates in v["entries"]:
                out.append("- " + ", ".join(crate_label(c) for c in crates))
                for n in dict.fromkeys(notices):
                    out.append("  - " + n)
            out.append("")
            out.append("```text\n%s\n```\n" % v["body"])

    if native_path:
        out.append(open(native_path, encoding="utf-8").read().rstrip("\n") + "\n")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
